INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (119, 271, 'COPY PAPER', '../upload/image/20181227/20181227113158_83229.jpg', '<p></p><p style="text-indent:20pt;"> <span style="font-size:16px;"><span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>COPY PAPER</strong></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">We have four production lines, which are 5# machine 6# machine 7# machine ,8#machine .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">And 8# machine is our best production line , this machine stablely manufacture the copy paper products for some</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">larger dealers for the yearly long-term contract .</span></span></span></p> <p style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Out month output are around 8000 Tons/Month :</span></span></p> <table border="1" width="87%"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="50%"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Production Lines ( Machine NO.)</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="50%"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Output ( Tons/Year )</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">8# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">4000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">7# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">6# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">5# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Total Amount</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">8000 Tons</span></span> </div> </td> </tr> </tbody> </table> <p align="left" style="text-indent:20pt;"> <span style="font-size:16px;"><span style=''font-family:"";''><br/> <span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">In China , we are one of the fewer factories who can offer only copy paper products per month which upto this quantity .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">We also import part of the raw mateiral(wooden pulp) from overseas like Russia and other area .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Additionally ,we are also one of the fewer factories who can offer only copy paper products in quality actual 100% wooden pulp best in China .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Introduction Of Copy Paper</span></span></span></span></p> <p align="left" style="text-indent:20pt;"> <span style="font-size:16px;"><span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">The Brand of our Copy Paper are "Phoenix" ,"Orient", "China Tiger" and so forth .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">The price bases on its quality , There are 3 prices of Copy Paper depending on its brightness in quality or material ,</span></span></span></p> <table border="1" width="88%"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item: 1</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item: 2</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item: 3</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="34%"> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Mixed Wooden Pulp</span></span></p> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Non-woodenfree)</span></span></p> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="32%"> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">100% Wooden Pulp</span></span></p> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Actual woodenfree)</span></span></p> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="34%"> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">100% Wooden Pulp</span></span></p> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Actual woodenfree)</span></span></p> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <table border="1" width="100%"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#